# WORKFLOW: your code owns the control flow; every path is known and testable
def refund_status_workflow(ticket: str) -> str:
    order_id = llm(f"Extract the order id, or NONE:\n{ticket}")      # step 1
    if order_id == "NONE":
        return ask_user("Which order is this about?")                 # code gate
    order = orders_api.get(order_id)                                  # step 2: plain code
    return llm(f"Explain this refund status to the customer:\n{order}")  # step 3

# AGENT: the model owns the control flow; your code owns tools, budget and stop
def support_agent(ticket: str, max_steps: int = 12) -> str:
    messages = [{"role": "user", "content": ticket}]
    for _ in range(max_steps):
        reply = llm_with_tools(messages, tools=[search_kb, get_order, issue_refund])
        if not reply.tool_calls:                 # the model decided it is done
            return reply.text
        messages += execute(reply.tool_calls)    # results steer the next step
    return escalate_to_human(ticket)             # budget hit: fail safe, not silent

# Production shape: predictable intents go to workflows, the long tail to the agent
WORKFLOWS = {"refund_status": refund_status_workflow}

def handle(ticket: str) -> str:
    intent = classify(ticket)  # cheap model, closed label set
    return WORKFLOWS.get(intent, support_agent)(ticket)
